import boto3


def filter_metric_dimensions(payload, config=None):
    config = config or {}
    client = boto3.client('cloudwatch', region_name=config.get('region', 'us-east-1'))
    response = client.get_metric_data(
        MetricDataQueries=[
            {
                'Id': 'm1',
                'MetricStat': {
                    'Metric': {
                        'Namespace': payload['namespace'],
                        'MetricName': payload['metric_name']
                    },
                    'Period': config.get('period', 300),
                    'Stat': 'Average'
                }
            }
        ],
        TimeRange={'Start': payload['start_time'], 'End': payload['end_time']}
    )
    dimensions = response['MetricDataResults'][0]['Dimensions']
    return {'dimensions': dimensions}

import requests


def compare_metric_series(payload, config=None):
    config = config or {}
    url = f"https://management.azure.com/subscriptions/{config['subscription_id']}/resourceGroups/{config['resource_group']}/providers/Microsoft.Compute/virtualMachines/{config['vm_name']}/providers/microsoft.insights/metrics?api-version=2018-01-01"
    headers = {
        'Authorization': f'Bearer {config['access_token']}',
        'Content-Type': 'application/json'
    }
    data = {
        'timespan': f"{payload['start_time']}/{payload['end_time']}",
        'interval': 'PT1M',
        'metricnames': payload['metric_names'],
        'aggregation': 'Average'
    }
    response = requests.post(url, headers=headers, json=data)
    response.raise_for_status()
    series = response.json()['value']
    return {'series': series}

import os


def get_config():
    return {
        'project_id': os.getenv('GOOGLE_CLOUD_PROJECT_ID'),
        'region': os.getenv('AWS_REGION', 'us-east-1'),
        'subscription_id': os.getenv('AZURE_SUBSCRIPTION_ID'),
        'resource_group': os.getenv('AZURE_RESOURCE_GROUP'),
        'vm_name': os.getenv('AZURE_VM_NAME'),
        'access_token': os.getenv('AZURE_ACCESS_TOKEN')
    }


def normalize_payload(payload):
    return {
        'metric': payload.get('metric', ''),
        'start_time': payload.get('start_time', ''),
        'end_time': payload.get('end_time', ''),
        'namespace': payload.get('namespace', ''),
        'metric_name': payload.get('metric_name', ''),
        'metric_names': payload.get('metric_names', [])
    }

import boto3


def metric_summary(payload, config=None):
    config = config or {}
    client = boto3.client('translate', region_name=config.get('region', 'us-east-1'))
    response = client.translate_text(
        Text=payload['text'],
        SourceLanguageCode='en',
        TargetLanguageCode='es'
    )
    return {'summary': response['TranslatedText']}

